def load_config(path):
    if not path:
        cfg = dict(DEFAULT_CONFIG)
    else:
        if not os.path.exists(path):
            print("配置文件不存在：%s" % path, file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        try:
            with open(path, "r", encoding="utf-8") as f:
                user_cfg = json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            print("配置文件解析失败：%s（%s）" % (path, e), file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        if not isinstance(user_cfg, dict):
            print("配置校验失败：配置根必须是 JSON 对象（dict）",
                  file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        cfg = dict(DEFAULT_CONFIG)
        cfg.update(user_cfg)
    cfg = _normalize_config(cfg)
    try:
        _validate_config_strict(cfg)
    except ConfigError as e:
        print("配置校验失败：%s" % e, file=sys.stderr)
        sys.exit(EXIT_CONFIG)
    return cfg


class _ConfigArgumentParser(argparse.ArgumentParser):

    def error(self, message):
        print("参数错误：%s" % message, file=sys.stderr)
        sys.exit(EXIT_CONFIG)


def main():
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    ap = _ConfigArgumentParser(description="美团更换手机号流程自动化")
    ap.add_argument("--phone", help="登录手机号（不填则在运行中提示输入，"
                                    "或用 --manual-login 从当前状态接管）")
    ap.add_argument("--serial", help="设备地址：emulator-5554 / ip:端口 "
                                    "（模拟器或无线调试直连，无需 adb）/ "
                                    "USB 序列号（需本机 adb server）；"
                                    "多设备时必填，单设备自动取")
    ap.add_argument("--adb-server", default=None,
                    help="本机 adb server 地址 host:port（默认 "
                         "127.0.0.1:%d，也可用环境变量 "
                         "ANDROID_ADB_SERVER_PORT）" % ADB_SERVER_PORT)
    ap.add_argument("--config",
                    help="JSON 配置文件路径（与内置默认配置逐字段合并，"
                         "只写要覆盖的字段；不指定即用内置默认值）")
    ap.add_argument("--manual-login", action="store_true",
                    help="跳过自动退出登录，从当前手机状态直接接管（适合人工先操作一部分）")
    ap.add_argument("--fresh-identity", action="store_true",
                    help="运行前执行身份重置：pm clear + 换 Android ID + "
                         "首启注册新 dfpId（用于绕开设备级风控关联，见 README）")
    ap.add_argument("--observe-net", action="store_true",
                    help="被动采样运行期间设备的 TCP 远端端点（netstat 轮询，"
                         "纯本地观测，写 logs/net_endpoints.log，供协议分析取证）")
    ap.add_argument("--valid-hours", type=float, default=None,
                    help="脚本有效期（小时），如 48；不填读配置"
                         "（内置默认 48，0=不限制）")
    ap.add_argument("--log-level", default=None, help="DEBUG/INFO/WARN/ERROR")
    args = ap.parse_args()

    cfg = load_config(args.config)
    if args.phone:
        phone = args.phone.strip()
        if not re.fullmatch(r"1\d{10}", phone):
            print("手机号非法：%r（应为 11 位大陆手机号，如 13800001234）"
                  % args.phone, file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        cfg["phone"] = phone
    if args.log_level:
        if args.log_level.upper() not in ("DEBUG", "INFO", "WARN", "ERROR"):
            print("未知 --log-level %r，回退 INFO（可选 DEBUG/INFO/WARN/ERROR）"
                  % args.log_level, file=sys.stderr)
            args.log_level = "INFO"
        cfg["log_level"] = args.log_level
    if args.valid_hours is not None:
        if not math.isfinite(args.valid_hours):
            print("--valid-hours 非法（不接受 nan/inf）", file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        if args.valid_hours < 0:
            print("--valid-hours 不能为负数（0=不限制）", file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        cfg["valid_hours"] = args.valid_hours

    log = Logger(level=cfg.get("log_level", "INFO"))
    log.info("=== 美团更换手机号自动化 %s 启动 ===" % SCRIPT_VERSION)
    log.info("日志文件：%s" % log.path)
    net_obs = None
    adb = None

    adb_server = None
    if args.adb_server:
        m = re.fullmatch(r"([\w.\-]+):(\d+)", args.adb_server.strip())
        if not m:
            print("参数错误：--adb-server 应为 host:port（如 "
                  "127.0.0.1:5037）", file=sys.stderr)
            sys.exit(EXIT_CONFIG)
        adb_server = (m.group(1), int(m.group(2)))

    try:
        if not Validity(float(cfg.get("valid_hours", 0)), log).check():
            sys.exit(EXIT_CONFIG)

        adb = ADB(serial=args.serial, adb_server=adb_server, logger=log,
                  recover_attempts=cfg.get("adb_recover_attempts", 2))
        devices = adb.list_devices()
        if not devices:
            log.error(_NO_DEVICE_MSG)
            sys.exit(EXIT_NO_DEVICE)
        if not adb.serial:
            if len(devices) > 1:
                log.error("检测到多台设备：%s，请用 --serial 指定" % ", ".join(devices))
                sys.exit(EXIT_NO_DEVICE)
            adb.serial = devices[0]

        if args.serial and args.serial not in devices:
            log.error("指定设备 %s 不在线（当前在线：%s）"
                      % (args.serial, ", ".join(devices)))
            sys.exit(EXIT_NO_DEVICE)
        log.info("使用设备：%s" % adb.serial)
        w, h = adb.screen_size()
        log.info("屏幕：%dx%d" % (w, h))
        try:
            if adb.wake_and_unlock():
                log.info("屏幕已唤醒，USB 供电期间保持常亮（stayon usb）")
            else:
                log.warn("设备疑似有安全锁（图案/指纹/密码）未解开：请手动"
                         "解锁后重跑，否则流程可能静默失败。本次仍继续执行")
        except Exception as e:
            log.warn("唤醒/解锁检查异常（不中断，继续执行）：%s" % e)

        if (w, h) != (1080, 2400):
            log.warn("当前分辨率 %dx%d 与校准基准 1080x2400 不同：坐标会按"
                     "比例自动缩放，但 coord_steps/slider_band/min_btn_width"
                     " 建议按实机复核" % (w, h))

        flow = Flow(adb, cfg, log)
        flow.ensure_app_installed()
        if args.fresh_identity:
            cfg["fresh_identity"] = True
        if cfg.get("fresh_identity"):
            flow.fresh_identity()
        if args.manual_login or cfg.get("manual_login"):
            log.info("手动模式：保留当前页面，直接接管")
        else:
            adb.force_stop()
            _sleep(1.5)
            log.info("兜底重置：强杀美团冷启动回主页，再检查登录态")
        adb.launch_app()
        _sleep(cfg.get("launch_wait_sec", 6))

        if getattr(args, "observe_net", False):
            try:
                net_obs = NetObserver(
                    adb, os.path.join(os.path.dirname(_log_path_of(log)) or ".",
                                      "net_endpoints.log"))
                net_obs.start()
                log.info("端点采样已启动（--observe-net）：%s" % net_obs.path)
            except Exception as e:
                log.warn("端点采样启动失败（不影响主流程）：%s" % e)
                net_obs = None

        def _net_finish():
            if net_obs is None:
                return
            n = net_obs.stop()
            log.info("端点采样结束：去重远端端点 %d 个 → %s"
                     % (n, net_obs.path))

        def _summary_line(code, category, flow=None):
            d = {"exit": code, "category": category,
                 "version": SCRIPT_VERSION,
                 "serial": getattr(adb, "serial", ""),
                 "phone": _mask_phone(cfg.get("phone"))}
            if flow is not None:
                d["slider_swipes"] = getattr(flow, "slider_swipes", 0)
                d["connect_attempts"] = getattr(flow, "connect_attempts", 0)
                d["next_submits"] = getattr(flow, "_next_submits_used", 0)
            if net_obs is not None:
                d["net_endpoints"] = len(net_obs._seen)
            print("[SUMMARY] %s" % json.dumps(d, ensure_ascii=False),
                  file=sys.stderr)

        def _fail(exc):
            code = classify_failure(exc)
            category = {EXIT_NO_DEVICE: "adb", EXIT_TIMEOUT: "timeout",
                        EXIT_STUCK: "stuck", EXIT_CONFIG: "config",
                        EXIT_RISK: "risk",
                        EXIT_RATELIMIT: "ratelimit"}.get(code, "stuck")
            _net_finish()
            _summary_line(code, category)
            print("[FAILURE] category=%s log=%s"
                  % (category, _log_path_of(log)), file=sys.stderr)
            log.error(str(exc))
            sys.exit(code)

        try:
            if args.manual_login or cfg.get("manual_login"):
                log.info("手动模式：跳过自动退出登录，从当前状态直接接管")
            else:
                if not cfg.get("phone"):
                    phone = _prompt_phone()
                    if not phone:
                        log.error("未提供手机号：加 --phone，或直接运行时"
                                  "按提示输入，或使用 --manual-login")
                        sys.exit(EXIT_CONFIG)
                    cfg["phone"] = phone
                flow.ensure_logged_out(
                    timeout=cfg.get("logout_timeout_sec", 150))
                flow.back_to_home(
                    timeout=cfg.get("passport_timeout_sec", 60))

            if not flow.at_change_phone_flow():
                flow.goto_passport_page(
                    timeout=cfg.get("passport_timeout_sec", 60))
                shot = flow.run_coord_flow()
            else:
                shot = flow.resume_change_phone_flow()
        except ConfigError as e:
            _fail(e)
        except TimeoutError as e:
            _fail(e)
        except RuntimeError as e:
            _fail(e)

        log.info("=== 完成 === 交付截图：%s" % os.path.abspath(shot))
        _net_finish()
        _summary_line(EXIT_OK, "success", flow)
        print("\n[DELIVERABLE] %s" % os.path.abspath(shot))
        sys.exit(EXIT_OK)

    except AdbError as e:
        print("[FAILURE] category=adb log=%s"
              % _log_path_of(log), file=sys.stderr)
        log.error("ADB 错误（设备离线/命令失败，若流程已开始可能为执行"
                  "中途掉线）：%s" % e)
        sys.exit(EXIT_NO_DEVICE)
    except KeyboardInterrupt:
        log.warn("用户中断")
        sys.exit(130)

    finally:
        if net_obs is not None:
            try:
                net_obs.stop()
            except Exception:
                pass
        if adb is not None:
            try:
                adb.restore_screen_policy()
            except Exception:
                pass
        log.close()


if __name__ == "__main__":
    main()
